function net = import_lstm(weights_path, vocab_path)\n%IMPORT_LSTM Load exported weights into a MATLAB network structure.\narguments\n    weights_path (1, :) char\n    vocab_path (1, :) char\nend\nS = load(weights_path);\nfid = fopen(vocab_path, 'r');\nraw = fread(fid, '*char')';\nfclose(fid);\nvocab = jsondecode(raw);\nfields = fieldnames(S);\nparams = struct();\nfor i = 1:numel(fields)\n    params.(fields{i}) = S.(fields{i});\nend\nnet = struct('Params', params, 'Vocabulary', vocab);\nend\n
